       line-height: 1.6;
     }

     form {
       margin-top: 1.5rem;
     }

     .form-field {
       display: grid;
       gap: 0.5rem;
       padding: 1rem;
       border: 1px solid var(--panel-border);
       border-radius: 1rem;
       background: rgba(15, 23, 42, 0.85);
     }

     .checkbox-row {
       display: flex;
       align-items: flex-start;
       gap: 0.75rem;
       min-width: 0;
