  <title>Terms of Use Consent</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: #111827;
      --panel-border: #253045;
      --text: #f9fafb;
      --muted: #cbd5e1;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --success: #86efac;
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
