    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 32%),
        linear-gradient(180deg, #020617 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: -3rem;
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: var(--text);
      color: #020617;
      font-weight: 700;
      text-decoration: none;
      z-index: 10;
    }

    .skip-link:focus {
      top: 1rem;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 30rem);
      padding: 2rem;
      border: 1px solid var(--panel-border);
      border-radius: 1.25rem;
      background: rgba(17, 24, 39, 0.92);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(1.75rem, 4vw, 2.2rem);
      line-height: 1.15;
    }

    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      margin-top: 1.5rem;
    }

    .form-field {
      display: grid;
      gap: 0.5rem;
      padding: 1rem;
      border: 1px solid var(--panel-border);
      border-radius: 1rem;
      background: rgba(15, 23, 42, 0.85);
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      min-width: 0;
    }

    input[type="checkbox"] {
      width: 1.1rem;
      height: 1.1rem;
      margin-top: 0.2rem;
      accent-color: var(--accent-strong);
      flex: 0 0 auto;
    }

    label {
      font-weight: 600;
      line-height: 1.5;
    }

    .helper-text {
      margin-left: 1.85rem;
      font-size: 0.95rem;
    }

    .error-text {
      margin-left: 1.85rem;
      font-size: 0.95rem;
      color: #fca5a5;
      font-weight: 600;
    }

    button {
      margin-top: 1rem;
      width: 100%;
      padding: 0.95rem 1.1rem;
      border: 0;
      border-radius: 0.9rem;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #eff6ff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 140ms ease, filter 140ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    :focus-visible {
      outline: 3px solid #bfdbfe;
      outline-offset: 3px;
    }

    .status-message {
      min-height: 1.5rem;
      margin-top: 0.75rem;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.5rem;
      }

      .helper-text {
        margin-left: 0;
      }
    }

    @media (forced-colors: active) {
      .card,
      .form-field,
      button {
        border: 1px solid ButtonText;
        background: Canvas;
        color: CanvasText;
        box-shadow: none;
      }

      .skip-link {
        background: Canvas;
        color: CanvasText;
        border: 1px solid ButtonText;
      }

      button {
        background: ButtonFace;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content"></main>
  <script>
    function ConsentField() {
      return `
        <div class="form-field">
          <div class="checkbox-row">
            <input id="termsConsent" name="termsConsent" type="checkbox" required aria-describedby="termsConsentHelp termsConsentError">
            <label for="termsConsent">I agree to the terms of use.</label>
          </div>
          <p id="termsConsentHelp" class="helper-text">Required to continue.</p>
          <p id="termsConsentError" class="error-text" aria-live="assertive"></p>
        </div>
      `;
    }

    function SubmitButton() {
      return '<button type="submit">Submit</button>';
    }

    function App() {
      return `
        <section class="card" aria-labelledby="page-title">
          <h1 id="page-title">Confirm your consent</h1>
          <p>Please review the requirement below before submitting the form.</p>
          <form id="consentForm" novalidate>
            ${ConsentField()}
            ${SubmitButton()}
            <p id="statusMessage" class="status-message" aria-live="polite"></p>
          </form>
        </section>
      `;
    }

    document.getElementById("main-content").innerHTML = App();

    const form = document.getElementById("consentForm");
    const checkbox = document.getElementById("termsConsent");
    const checkboxError = document.getElementById("termsConsentError");
    const statusMessage = document.getElementById("statusMessage");

    function setCheckboxError(message) {
      checkbox.setAttribute("aria-invalid", String(Boolean(message)));
      checkboxError.textContent = message;
    }

    checkbox.addEventListener("change", function () {
      if (checkbox.checked) {
        setCheckboxError("");
      }
    });

    form.addEventListener("submit", function (event) {
      if (!form.checkValidity()) {
        event.preventDefault();
        setCheckboxError("Please agree before submitting.");
        checkbox.focus();
        statusMessage.textContent = "";
        return;
      }

      event.preventDefault();
      setCheckboxError("");
      statusMessage.textContent = "Consent submitted successfully.";
    });
  </script>
</body>
</html>
